import type { BuildValidationResult } from '@mintlify/previewing';
import type { Root } from 'mdast';

export type Group = 'content' | 'nav' | 'config' | 'openapi';

export const GROUPS: Group[] = ['content', 'nav', 'config', 'openapi'];

export type Severity = 'error' | 'warning';

export type Edit = { start: number; end: number; text: string };

export type FileEdit = Edit & { file: string };

/** A fix --fix applied: where it was and the text it replaced. */
export type Change = {
  rule: string;
  file: string;
  line?: number;
  column?: number;
  before: string;
  after: string;
};

export type Diagnostic = {
  rule: string;
  group: Group;
  severity: Severity;
  file: string;
  line?: number;
  column?: number;
  message: string;
  fix?: FileEdit;
};

/** What a rule reports; the engine adds its id and group, and its severity unless overridden. */
export type Finding = Omit<Diagnostic, 'rule' | 'group' | 'severity'> & { severity?: Severity };

type RuleMeta = {
  id: string;
  group: Group;
  severity: Severity;
  needsBuild?: boolean;
  description: string;
};

export type DiagnosticSource = Pick<RuleMeta, 'id' | 'group' | 'severity' | 'description'>;

export type FileKind = 'page' | 'snippet';

export type FileContext = {
  file: string;
  content: string;
  baseDir: string;
  frontmatter: Record<string, unknown>;
  tree: Root;
  readFile?: (file: string) => string | undefined;
  anchorLinks?: ReadonlySet<string>;
};

/** A finding in one file, with an optional edit against the content the rule saw. */
export type FileFinding = {
  line?: number;
  column?: number;
  message: string;
  edit?: Edit;
};

/** Checks one page or snippet at a time. Raw rules read text; the rest also get the MDX tree. */
export type FileRule = RuleMeta & {
  scope: 'file';
  raw?: boolean;
  pagesOnly?: boolean;
  needsAnchorLinks?: boolean;
  check: (context: FileContext) => FileFinding[];
};

export type SiteFile = { file: string; kind: FileKind };

export type BuildResult = BuildValidationResult;

export type Site = {
  baseDir: string;
  files: SiteFile[];
  /** Set with --files: rules report on these files only. */
  selected?: ReadonlySet<string>;
  configFile: string;
  variables?: Record<string, string>;
  build?: BuildResult;
  /** The line and column of the first occurrence of text in a file. */
  locate: (file: string, text: string) => { line?: number; column?: number };
  read: (file: string) => string | undefined;
  localSchema: boolean;
};

/** Checks the site as a whole. */
export type SiteRule = RuleMeta & {
  scope: 'site';
  check: (site: Site) => Finding[] | Promise<Finding[]>;
};

export type Rule = FileRule | SiteRule;
